// Simulated AWS security findings (no external API call).
const cfg = $input.first().json;

const mockFindings = [
  {
    id: 'finding-' + Date.now(),
    type: 'IAMPolicyChange',
    resource: 'arn:aws:iam::' + cfg.awsAccountId + ':role/example-role',
    description: 'IAM policy modified to include additional permissions',
    detectedAt: new Date().toISOString()
  },
  {
    id: 'finding-' + (Date.now() + 1),
    type: 'SecurityGroupChange',
    resource: 'sg-0123456789abcdef0',
    description: 'Ingress rule opened on port 22 from 0.0.0.0/0',
    detectedAt: new Date().toISOString()
  }
];

return [{
  json: {
    ...cfg,
    findings: mockFindings
  }
}];

// Compares the freshly generated security findings/policy snapshot against the
// last known version stored in workflow static data (per AWS account). No external DB needed.
const cfg = $('Set AWS Configuration Params').first().json;
const response = $input.first().json;
const newFindingsText = JSON.stringify(response.findings || response.results || response);

const staticData = $getWorkflowStaticData('node');
if (!staticData.findingsByAccount) staticData.findingsByAccount = {};

const previous = staticData.findingsByAccount[cfg.awsAccountId];
const previousFindingsText = previous ? previous.findingsText : null;
const findingsChanged = previousFindingsText !== null && previousFindingsText !== newFindingsText;
const isFirstSeen = previousFindingsText === null;

return [{
  json: {
    ...cfg,
    newFindingsText,
    previousFindingsText: previousFindingsText || '',
    findingsChanged: findingsChanged || isFirstSeen,
    isFirstSeen,
    checkedAt: new Date().toISOString()
  }
}];

// Simulated AWS account asset inventory (no external API call).
const upstream = $input.first().json;

const mockAssets = {
  resources: [
    'arn:aws:s3:::example-bucket',
    'arn:aws:ec2:' + upstream.awsRegion + ':' + upstream.awsAccountId + ':instance/i-0123456789abcdef0'
  ],
  iamRoles: ['arn:aws:iam::' + upstream.awsAccountId + ':role/example-role'],
  environment: 'production',
  vpcs: ['vpc-0123456789abcdef0']
};

return [{
  json: {
    ...upstream,
    resources: mockAssets.resources,
    iamRoles: mockAssets.iamRoles,
    environment: mockAssets.environment,
    vpcs: mockAssets.vpcs
  }
}];

const findingsState = $('Check Changes in Findings').first().json;
const assetData = $input.first().json;

return [{
  json: {
    ...findingsState,
    affectedResources: assetData.resources || assetData.affectedResources || [],
    affectedIamRoles: assetData.iamRoles || assetData.affectedIamRoles || [],
    accountEnvironment: assetData.environment || assetData.env || '',
    vpcNetworks: assetData.vpcs || assetData.networks || []
  }
}];

