const upstream = $('Merge Security and Asset Details').first().json;
const response = $input.first().json;

let parsed = {
  changeSummary: '',
  changedItems: [],
  severity: 'High',
  severityReasoning: 'AI analysis unavailable this cycle; defaulted to High for manual review.',
  complianceFrameworksImpacted: [],
  requiredActionsSecOps: [],
  requiredActionsCompliance: []
};
try {
  const raw = String(response.output || response.text || response.response || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  // keep safe default above
}

return [{
  json: {
    ...upstream,
    changeSummary: parsed.changeSummary || '',
    changedItems: parsed.changedItems || [],
    severity: parsed.severity || 'High',
    severityReasoning: parsed.severityReasoning || '',
    complianceFrameworksImpacted: parsed.complianceFrameworksImpacted || [],
    requiredActionsSecOps: parsed.requiredActionsSecOps || [],
    requiredActionsCompliance: parsed.requiredActionsCompliance || []
  }
}];

