// Persist the new findings/policy snapshot as the baseline for next cycle's diff,
// scoped per AWS account in workflow static data.
const item = $input.first().json;
const staticData = $getWorkflowStaticData('node');
if (!staticData.findingsByAccount) staticData.findingsByAccount = {};

staticData.findingsByAccount[item.awsAccountId] = {
  findingsText: item.newFindingsText,
  updatedAt: new Date().toISOString(),
  lastSeverity: item.severity
};

return [{ json: { ...item, baselineUpdated: true } }];
